file.content:
        self.dependencies = layer;
        self
    }

    /// A context for the same project over a larger dependency `layer`, with empty memos. Everything about the project
    /// that a layer cannot change is shared with this one rather than built again: the merged source data, the import
    /// map and `named_types` declarations, the module resolvers (and their file-system caches), the tsconfig check, and
    /// the bare-name indexes. `named_types` is the project's index with `layer` as its fallback.
    pub(crate) fn over_layer(
        &self,
        named_types: Arc<crate::named_type_index::NamedTypeIndex>,
        layer: Option<Arc<crate::dependency_types::DependencyLayer>>,
    ) -> Self {
        let import_map = self.import_map.with_fallback(layer.as_ref().map(|layer| layer.import_map.clone()));
        Self {
            global: self.global.clone(),
            import_map: Arc::new(import_map),
            named_types,
            oxc_resolver: self.oxc_resolver.clone(),
            types_first_resolver: self.types_first_resolver.clone(),
            module_resolutions: Default::default(),
            react_types_files: Default::default(),
            shared_props: Default::default(),
            member_reads: Default::default(),
            props_reads: Default::default(),
            extra_builtins: self.extra_builtins.clone(),
            mapping_index: self.mapping_index.clone(),
            enum_bare_index: self.enum_bare_index.clone(),
            const_array_bare_index: self.const_array_bare_index.clone(),
            html_attributes: self.html_attributes,
            ambient_global_files: self.ambient_global_files.clone(),
            tsconfig_diagnostic: self.tsconfig_diagnostic.clone(),
            interface_chains: Default::default(),
            named_results: memo::NamedResults::with_max_reads(NAMED_RESULT_MAX_READS),
            attribute_reads: memo::Memo::with_max_reads(NAMED_RESULT_MAX_READS),
            attribute_names: Default::default(),
            dependencies: layer,
            react_types: self.react_types.clone(),
            collapse_inherited_props: self.collapse_inherited_props,
        }
    }

    /// Whether `file` is a loaded dependency file.
    pub(crate) fn is_dependency_file(&self, file: &Utf8Path) -> bool {
        self.dependencies.as_ref().is_some_and(|layer| layer.is_dependency_file(file))
    }

    /// Whether this run can collapse any source; `expand_all` is set only then, since it splits shared chains.
    pub(crate) fn can_collapse(&self) -> bool {
        use crate::types::options::CollapseInheritedProps;
        match self.collapse_inherited_props {
            CollapseInheritedProps::Dependencies => self.dependencies.is_some(),
            CollapseInheritedProps::All => true,
            CollapseInheritedProps::None => false,
        }
    }

    /// Whether a source of type `type_name` declaring `declared` props in `file`, reached at `depth`, is recorded as a
    /// layer instead of expanded (collapse). Depth 0 is the component's own props type. React's and TypeScript's own
    /// declarations stay with `html_attributes` even under `All`.
    ///
    /// A dependency source collapses when it is ambient (`ambient`: DOM and ARIA attributes, style systems) and past
    /// `COLLAPSE_THRESHOLD` props, or when it is not ambient but past `LARGE_API_SOURCE` props. Otherwise it is listed:
    /// what a dependency's component exposes is the API a reader needs typed, and a small ambient source costs more as
    /// a layer than as props. A project source (`All` only) collapses past `COLLAPSE_THRESHOLD` props, as before.
    pub(crate) fn collapses(
        &self,
        file: &Utf8Path,
        type_name: &str,
        declared: usize,
        depth: u8,
        state: &ResolveState,
    ) -> bool {
        use crate::types::options::CollapseInheritedProps;
        let large = declared > COLLAPSE_THRESHOLD;
        let dependency = || {
            self.is_dependency_file(file)
                && if ambient::is_ambient_source(file.as_str(), type_name) {
                    large
                } else {
                    declared > LARGE_API_SOURCE
                }
        };
        depth > 0
            && !state.expand_all
            && match self.collapse_inherited_props {
                CollapseInheritedProps::Dependencies => dependency(),
                CollapseInheritedProps::All => {
                    if self.is_dependency_file(file) {
                        dependency()
                    } else {
                        large && !crate::dependency_types::in_node_modules(file.as_str())
                    }
                }
                CollapseInheritedProps::None => false,
            }
    }
}

/// A source declaring more than this many props can collapse: an ambient dependency source (see `ambient`), or a
/// project source under `CollapseInheritedProps::All`. Storybook's react-component-meta hides a dependency source
/// contributing more than this many props, whatever it contains; here an API source is hidden only past
/// `LARGE_API_SOURCE`.
pub(crate) const COLLAPSE_THRESHOLD: usize = 30;

/// A dependency source that is not ambient by name still collapses past this many props: it is a style system under
/// a name the rule does not know, not an API. Chakra v3's `SystemProperties` declares 705 and, listed, took a
/// four-component app from 516 KB to 1.96 MB; the largest source that is an API in the pinned corpora and in apps
/// on Chakra, Mantine and MUI declares 75 (`docs/measurement.md`, "Collapse by relevance").
pub(crate) const LARGE_API_SOURCE: usize = 200;

/// Changes whenever the options could change what a specifier resolves to: the resolver configuration, the governing
/// tsconfig and its modification time, and the build. Keys the dependency loader's persisted index.
pub(crate) fn resolution_fingerprint(options: &PipelineOptions) -> u64 {
    let tsconfig = governing_tsconfig(options);
    let tsconfig_mtime = tsconfig
        .as_ref()
        .and_then(|path| std::fs::metadata(path).ok()?.modified().ok())
        .and_then(|time| time.duration_since(std::time::UNIX_EPOCH).ok())
        .map(|age| age.as_nanos());
    let text = format!(
        "{:?}|{:?}|{:?}|{}",
        resolve_options(options),
        tsconfig,
        tsconfig_mtime,
        env!("CALIPER_SOURCE_FINGERPRINT"),
    );
    text.bytes()
        .fold(0xcbf2_9ce4_8422_2325_u64, |hash, byte| (hash ^ u64::from(byte)).wrapping_mul(0x0000_0100_0000_01b3))
}

//! Which inherited dependency sources are ambient: what every element has, or a style system, which a reader would not
//! lead with. The resolver collapses the large ones into a layer (names only) and lists every other dependency source,
//! which is the API a dependency's component exposes (its modes, state and composition).
//!
//! Which clause fits reads only the source's file, its type name and a prop's name; the resolver adds its size (below). It
//! is the rule measured in the "Layer-only props" section of `docs/measurement.md`; the test
//! `the_rule_gives_the_clause_the_oracles_classifier_gives` keeps this module equal to that classifier's recorded
//! verdicts. The first clause that fits decides:
//!
//! 1. **dom file**: the source's file is `@types/react`, or react-aria's `@react-types/shared/src/dom.d.ts`
//! 2. **dom type**: the source's type is a DOM family: `GlobalDOMEvents`, `DOMAttributes`, `AriaAttributes`,
//!    `AllHTMLAttributes`, `SVGAttributes`, `*HTMLAttributes`, `Aria*Attributes`
//! 3. **style type**: the source's type is a style system: `*StyleProps`, `*StyleProp`, `SystemProps`,
//!    `Space|Layout|Color|Typography|Border|Flex|Grid|Position|Shadow|Background` + `Props`
//! 4. **global attribute**: the prop is one every element has, or starts `aria-` or `data-`
//! 5. **dependency api**: anything else
//!
//! Clauses 1 to 3 decide a whole source: an ambient source is one the resolver may collapse, and only when it is also
//! large (`ResolutionContext::collapses`: a layer record costs more than a handful of props, and listing a small
//! ambient source gives `aria-label` and `id` their types). Clause 4 decides a prop of a source the first three did not
//! match; it never collapses a source on its own. A source that is API (clause 5) collapses only past
//! `LARGE_API_SOURCE` props, which no API measured on the pinned corpora and on apps reaches.
//!
//! Clause 4 is not part of the production rule: the resolver decides per source (`is_ambient_source`, clauses 1 to 3)
//! and never reads a prop's name. It is kept under `#[cfg(test)]` so the parity test can compare the whole classifier,
//! not only the source verdicts, with the oracle's.

/// The attributes every element has, which no component's API is about. `defaultValue`, `value`, `type`, `name` and
/// the like are not here: they are element-specific, and a dependency's component often uses them as its own API.
#[cfg(test)]
const GLOBAL_ATTRIBUTES: &[&str] = &[
    "className",
    "style",
    "id",
    "title",
    "lang",
    "dir",
    "hidden",
    "tabIndex",
    "role",
    "slot",
    "accessKey",
    "draggable",
    "contentEditable",
    "spellCheck",
    "translate",
    "inputMode",
    "nonce",
];

/// Type names of the DOM families that are named exactly (the rest end in `HTMLAttributes` or are `Aria*Attributes`).
const DOM_TYPES: &[&str] =
    &["GlobalDOMEvents", "DOMAttributes", "AriaAttributes", "AllHTMLAttributes", "SVGAttributes"];

/// The style-system prefixes that, with `Props`, name a style source (`SpaceProps`, `LayoutProps`, ...).
const STYLE_PREFIXES: &[&str] =
    &["Space", "Layout", "Color", "Typography", "Border", "Flex", "Grid", "Position", "Shadow", "Background"];

/// Which clause of the rule decided. Only the parity test with the oracle's classifier reads the per-prop verdict; the
/// resolver needs the whole-source clauses (`is_ambient_source`).
#[cfg(test)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Why {
    /// The source's file is a DOM declaration file (clause 1).
    DomFile,
    /// The source's type is a DOM family (clause 2).
    DomType,
    /// The source's type is a style system (clause 3).
    StyleType,
    /// The prop is one every element has (clause 4).
    GlobalAttribute,
    /// None of the above: a dependency's own API (clause 5).
    DependencyApi,
}

#[cfg(test)]
impl Why {
    /// Whether the prop is ambient (clauses 1 to 4) and not API (clause 5).
    fn is_ambient(self) -> bool {
        self != Self::DependencyApi
    }
}

/// `\w*` in the rule: letters, digits and underscore.
fn is_word(text: &str) -> bool {
    text.chars().all(|c| c.is_ascii_alphanumeric() || c == '_')
}

fn is_dom_file(file: &str) -> bool {
    file.contains("/@types/react/")
        || file
            .rsplit_once("/@react-types/shared/src/")
            .is_some_and(|(_, name)| matches!(name, "dom.d.ts" | "dom.d.mts" | "dom.d.cts"))
}

fn is_dom_type(type_name: &str) -> bool {
    DOM_TYPES.contains(&type_name)
        || type_name.strip_suffix("HTMLAttributes").is_some_and(is_word)
        || type_name.strip_prefix("Aria").and_then(|rest| rest.strip_suffix("Attributes")).is_some_and(is_word)
}

fn is_style_type(type_name: &str) -> bool {
    type_name == "SystemProps"
        || type_name.strip_suffix("StyleProps").or_else(|| type_name.strip_suffix("StyleProp")).is_some_and(is_word)
        || STYLE_PREFIXES.iter().any(|prefix| type_name.strip_prefix(prefix) == Some("Props"))
}

/// Whether `prop` is one every element has, or an `aria-` or `data-` attribute (clause 4).
#[cfg(test)]
fn is_global_attribute(prop: &str) -> bool {
    GLOBAL_ATTRIBUTES.contains(&prop) || prop.starts_with("aria-") || prop.starts_with("data-")
}

/// Whether a source in `file` declaring the type `type_name` is ambient as a whole (clauses 1 to 3), so the resolver may
/// record it as a layer of names instead of listing its props (it does when the source is also large).
pub(crate) fn is_ambient_source(file: &str, type_name: &str) -> bool {
    is_dom_file(file) || is_dom_type(type_name) || is_style_type(type_name)
}

/// The rule for one prop a collapsed source names: the clause that decided and so whether it is ambient or API.
#[cfg(test)]
fn classify(file: &str, type_name: &str, prop: &str) -> Why {
    if is_dom_file(file) {
        Why::DomFile
    } else if is_dom_type(type_name) {
        Why::DomType
    } else if is_style_type(type_name) {
        Why::StyleType
    } else if is_global_attribute(prop) {
        Why::GlobalAttribute
    } else {
        Why::DependencyApi
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use rstest::rstest;

    const REACT: &str = "/p/node_modules/@types/react/index.d.ts";
    const ARIA_DOM: &str = "/p/node_modules/@react-types/shared/src/dom.d.ts";
    const ARIA_DOM_MTS: &str = "/p/node_modules/@react-types/shared/src/dom.d.mts";
    const ARIA_EVENTS: &str = "/p/node_modules/@react-types/shared/src/events.d.ts";
    const PKG: &str = "/p/node_modules/x/index.d.ts";

    #[rstest]
    #[case(REACT, "Anything", "foo", Why::DomFile)]
    #[case(ARIA_DOM, "GlobalDOMEvents", "onClick", Why::DomFile)]
    #[case(ARIA_DOM_MTS, "Other", "x", Why::DomFile)]
    #[case(ARIA_EVENTS, "KeyboardEvents", "onKeyDown", Why::DependencyApi)]
    #[case(PKG, "GlobalDOMEvents", "onClick", Why::DomType)]
    #[case(PKG, "DOMAttributes", "onClick", Why::DomType)]
    #[case(PKG, "AriaAttributes", "aria-label", Why::DomType)]
    #[case(PKG, "AllHTMLAttributes", "href", Why::DomType)]
    #[case(PKG, "SVGAttributes", "d", Why::DomType)]
    #[case(PKG, "HTMLAttributes", "dir", Why::DomType)]
    #[case(PKG, "ButtonHTMLAttributes", "type", Why::DomType)]
    #[case(PKG, "AriaLabelingAttributes", "aria-label", Why::DomType)]
    #[case(PKG, "AriaAttributesExtra", "foo", Why::DependencyApi)]
    #[case(PKG, "Aria_Attributes", "foo", Why::DomType)]
    #[case(PKG, "Aria-Attributes", "foo", Why::DependencyApi)]
    #[case(PKG, "StyleProps", "margin", Why::StyleType)]
    #[case(PKG, "JsxStyleProps", "margin", Why::StyleType)]
    #[case(PKG, "ViewStyleProp", "margin", Why::StyleType)]
    #[case(PKG, "SystemProps", "margin", Why::StyleType)]
    #[case(PKG, "SpaceProps", "m", Why::StyleType)]
    #[case(PKG, "BackgroundProps", "bg", Why::StyleType)]
    #[case(PKG, "Props", "m", Why::DependencyApi)]
    #[case(PKG, "ColorsProps", "m", Why::DependencyApi)]
    #[case(PKG, "StylePropsExtra", "m", Why::DependencyApi)]
    #[case(PKG, "DialogProps", "className", Why::GlobalAttribute)]
    #[case(PKG, "DialogProps", "aria-label", Why::GlobalAttribute)]
    #[case(PKG, "DialogProps", "data-testid", Why::GlobalAttribute)]
    #[case(PKG, "DialogProps", "tabIndex", Why::GlobalAttribute)]
    #[case(PKG, "DialogProps", "value", Why::DependencyApi)]
    #[case(PKG, "DialogProps", "defaultValue", Why::DependencyApi)]
    #[case(PKG, "DialogProps", "type", Why::DependencyApi)]
    #[case(PKG, "DialogProps", "name", Why::DependencyApi)]
    #[case(PKG, "DialogProps", "disabled", Why::DependencyApi)]
    #[case(PKG, "DialogProps", "Aria-label", Why::DependencyApi)]
    fn the_clause_that_decides_is_the_first_that_fits(
        #[case] file: &str,
        #[case] type_name: &str,
        #[case] prop: &str,
        #[case] expected: Why,
    ) {
        assert_eq!(classify(file, type_name, prop), expected);
    }

    /// `ambient_parity.json` holds the verdicts of the TypeScript classifier of the "Layer-only props" measurement
    /// (`docs/measurement.md`) for every distinct (file, type, prop) a collapsed layer names on antd and shadcn, plus
    /// synthetic edge cases (`/p/node_modules/x/index.d.ts`) for the style-system and DOM-type clauses, which those two
    /// corpora do not exercise (the verdicts are the classifier's, not written by hand). Chakra, Mantine and Spectrum
    /// are not in the data. This module must give the same clause for each.
    #[test]
    fn the_rule_gives_the_clause_the_oracles_classifier_gives() {
        let rows: Vec<serde_json::Value> = serde_json::from_str(include_str!("ambient_parity.json")).unwrap();
        assert!(rows.len() > 500, "{} rows", rows.len());
        let mut seen = std::collections::BTreeSet::new();
        for row in &rows {
            let text = |key: &str| row[key].as_str().unwrap_or_else(|| panic!("{key} in {row}"));
            let (file, type_name, prop, label) = (text("file"), text("type"), text("prop"), text("why"));
            let expected = match label {
                "dom file" => Why::DomFile,
                "dom type" => Why::DomType,
                "style type" => Why::StyleType,
                "global attribute" => Why::GlobalAttribute,
                "dependency api" => Why::DependencyApi,
                other => panic!("unknown clause {other}"),
            };
            let got = classify(file, type_name, prop);
            assert_eq!(got, expected, "{file} {type_name} {prop}");
            assert_eq!(text("kind") == "ambient", got.is_ambient(), "{file} {type_name} {prop}");
            seen.insert(label.to_owned());
            // Clauses one to three decide a whole source, and so whether the resolver may collapse it.
            if matches!(expected, Why::DomFile | Why::DomType | Why::StyleType) {
                assert!(is_ambient_source(file, type_name), "{file} {type_name}");
            }
        }
        assert_eq!(seen.len(), 5, "every clause is covered: {seen:?}");
    }

    #[test]
    fn only_clauses_one_to_three_collapse_a_source() {
        assert!(is_ambient_source(REACT, "X"));
        assert!(is_ambient_source(PKG, "GlobalDOMEvents"));
        assert!(is_ambient_source(PKG, "SystemProps"));
        // A source of global attributes only is not collapsed on its own: clause 4 decides a prop, not a source.
        assert!(!is_ambient_source(PKG, "DialogProps"));
    }
}

//! Options for one extraction run.
//!
//! These live in `types/` so the resolver and the dependency loader can read them without importing `pipeline`;
//! `pipeline` re-exports them, so `caliper_docgen_core::pipeline::PipelineOptions` and the others keep their paths.

use camino::{Utf8Path, Utf8PathBuf};
use rustc_hash::FxHashSet;
use serde::{Deserialize, Serialize};

/// How much of an inherited HTML element's attribute surface to expose.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub enum HtmlAttributeMode {
    /// A compact subset per element: `ref`, `aria-*`, every event handler but the `*Capture` twins, the global
    /// attributes and the element's own notable ones, kept in `notableInherited`. Opt-in; `Full` is the default.
    Curated,
    /// Actually resolve `@types/react`'s real `HTMLAttributes`/`AriaAttributes`/
    /// `DOMAttributes`/`<Element>HTMLAttributes` interface chain, matching RDT's
    /// full ~250-300 attributes per element — the default.
    Full,
    /// Don't synthesize any inherited HTML attributes at all — own props only.
    None,
}

impl HtmlAttributeMode {
    /// The mode named by a config or binding string. `Err` carries the unrecognized value, so callers can name it
    /// instead of silently falling back to a default.
    pub fn parse(s: &str) -> Result<Self, &str> {
        match s {
            "curated" => Ok(Self::Curated),
            "full" => Ok(Self::Full),
            "none" => Ok(Self::None),
            other => Err(other),
        }
    }
}

/// Which inherited sources are recorded as an `InheritedLayer` of names instead of expanded prop by prop (collapse).
/// A component's own props type is always expanded. A dependency source collapses when it is ambient (DOM and ARIA
/// attributes, style systems) and declares more than 30 props; a dependency's own API is listed unless it declares more than 200 props.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub enum CollapseInheritedProps {
    /// Large ambient sources declared in a loaded dependency (`load_dependencies`).
    #[default]
    Dependencies,
    /// Those, and the project's own sources of more than 30 props.
    All,
    /// Expand every source.
    None,
}

impl CollapseInheritedProps {
    /// The mode named by a config or binding string. `Err` carries the unrecognized value.
    pub fn parse(s: &str) -> Result<Self, &str> {
        match s {
            "dependencies" => Ok(Self::Dependencies),
            "all" => Ok(Self::All),
            "none" => Ok(Self::None),
            other => Err(other),
        }
    }
}

/// Configuration for a single extraction run.
#[derive(Debug, Clone)]
pub struct PipelineOptions {
    /// Source directories to scan.
    pub src_dirs: Vec<Utf8PathBuf>,
    /// Extra gitignore-style glob patterns to exclude, relative to each source directory (on top of built-in: stories,
    /// tests, snapshots).
    pub exclude_patterns: Vec<String>,
    /// Component name prefixes to skip.
    pub exclude_prefixes: Vec<String>,
    /// How much of an inherited HTML element's attributes to expose.
    pub html_attributes: HtmlAttributeMode,
    /// Path to the tsconfig that governs module resolution. When unset, each importing file uses the nearest
    /// `tsconfig.json` above it, and the one above the first source directory supplies `customConditions`.
    pub tsconfig_path: Option<Utf8PathBuf>,
    /// Additional builtin type names beyond the React standard set.
    pub extra_builtins: FxHashSet<compact_str::CompactString>,
    /// Cache directory. Defaults to `node_modules/.cache/caliper-docgen` under the nearest ancestor of the first source
    /// directory that has a `node_modules` or a `package.json` (a directory in the OS temp directory when there is
    /// none), so the CLI, the Vite plugin and the Storybook addon share one cache whatever directory they run from.
    pub cache_dir: Option<Utf8PathBuf>,
    /// Read and write the on-disk caches (the declaration parse cache and the dependency index) under `cache_dir`.
    /// Off, a run reads and writes nothing there and parses everything; its output is the same. On by default.
    pub use_cache: bool,
    /// Load the dependency declarations project types reference, by name, before resolving (ADR 0010). On by default
    /// (`docs/performance.md`); off, a type imported from a package resolves only when it is a builtin or a known
    /// shortcut. A project with no installed packages loads nothing either way.
    pub load_dependencies: bool,
    /// Which large inherited sources to record as a layer instead of expanding.
    pub collapse_inherited_props: CollapseInheritedProps,
    /// Ask the built-in TypeScript checker for each component's props and merge them over the structural result
    /// (ADR 0026, `docs/type-checker-integration.md`). On by default; off, the structural resolver answers alone.
    /// `extract` ignores it: the checker backend lives in `caliper-docgen-semantic`, which depends on this crate, so
    /// the embedding (the CLI) runs it and calls [`crate::types::semantic::merge_semantic`].
    pub checker: bool,
}

impl Default for PipelineOptions {
    fn default() -> Self {
        Self {
            src_dirs: vec![Utf8PathBuf::from("./src")],
            exclude_patterns: vec![],
            exclude_prefixes: vec![],
            html_attributes: HtmlAttributeMode::Full,
            tsconfig_path: None,
            extra_builtins: Default::default(),
            cache_dir: None,
            use_cache: true,
            load_dependencies: true,
            collapse_inherited_props: CollapseInheritedProps::default(),
            checker: true,
        }
    }
}

impl PipelineOptions {
    /// Where the parse and dependency caches (and `extract`'s kept checker answer) live: `cache_dir` when set, else
    /// `node_modules/.cache/caliper-docgen` under the nearest ancestor of the first source directory that has a
    /// `node_modules` or a `package.json`, so running from another directory neither misses the project's cache nor
    /// creates a `node_modules` there. A source directory in no project gets a directory in the OS temp directory.
    pub fn effective_cache_dir(&self) -> Utf8PathBuf {
        if let Some(dir) = &self.cache_dir {
            return dir.clone();
        }
        const CACHE: &str = "node_modules/.cache/caliper-docgen";
        let root = canonicalize_first_src_dir(&self.src_dirs).and_then(|src| {
            src.ancestors()
                .find(|dir| dir.join("node_modules").is_dir() || dir.join("package.json").is_file())
                .map(Utf8Path::to_owned)
        });
        match root {
            Some(root) => root.join(CACHE),
            None => {
                let temp = std::env::temp_dir();
                Utf8PathBuf::from_path_buf(temp).unwrap_or_else(|_| Utf8PathBuf::from(".")).join("caliper-docgen-cache")
            }
        }
    }
}

/// Canonicalize `src_dirs`' first entry to use as the "from" directory for
/// resolving @types/react and TypeScript's own lib.d.ts files — must match
/// what discovered file paths look like (always absolute — the `ignore`
/// walker absolutizes them regardless of whether --src was given as relative
/// or absolute), since the resolver looks this same specifier up again
/// per-component relative to each file's own absolute directory. A relative
/// src_dirs entry has too few path components for oxc_resolver's ancestor
/// walk to ever reach the real node_modules tree, so it silently finds
/// nothing instead of the intended real package.
pub(crate) fn canonicalize_first_src_dir(src_dirs: &[Utf8PathBuf]) -> Option<Utf8PathBuf> {
    src_dirs.first().and_then(|dir| crate::canonical_path::canonicalize(dir).ok())
}

