            Arc::new(SemanticProp {
                name: format!("{prefix}{i}"),
                prop_type: PropType::String,
                required: false,
                description: String::new(),
                react_declared: false,
                tags: Default::default(),
                parent: Some(parent.clone()),
                declarations: vec![parent],
            })
        })
        .collect()
}

